for f in ~/.claude.json ~/.claude/settings.json ~/.claude/mcp.json ~/.claude/.mcp.json; do
  if [ -f "$f" ]; then
    echo "=== $f (zephyr block) ==="
    python3 - "$f" <<'PY' 2>/dev/null
import json,sys,re
p=sys.argv[1]
try:
    d=json.load(open(p))
except Exception as e:
    print("  (unparseable:",e,")"); raise SystemExit
def walk(o,path=""):
    if isinstance(o,dict):
        for k,v in o.items():
            if k.lower()=="zephyr" or (isinstance(k,str) and "zephyr" in k.lower()):
                s=json.dumps(v,indent=2)
                # redact any long secret-looking values
                s=re.sub(r'"([^"]{25,})"', lambda m: '"<REDACTED len=%d>"'%len(m.group(1)), s)
                print(f"  path={path}/{k}\n{s}")
            else:
                walk(v,path+"/"+str(k))
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,path+f"[{i}]")
walk(d)
PY
  fi
done
echo "=== env vars named *ZEPHYR* (names only) ==="
env | grep -i zephyr | sed 's/=.*/=<set>/' || echo "  (none in this shell)"

